local function applyReplacements(silent)
  RequestStreamedTextureDict('apocalypse_signs', false)
  local deadline = GetGameTimer() + 30000
  while not HasStreamedTextureDictLoaded('apocalypse_signs') and GetGameTimer() < deadline do
    Wait(100)
  end
  if not HasStreamedTextureDictLoaded('apocalypse_signs') then
    if not silent then
      print('^1[apocalypse-road-signs]^7 highway texture dictionary failed to load; retrying shortly')
    end
    return false
  end
  local count = 0
  for txd, textures in pairs(replacements) do
    for _, txn in ipairs(textures) do
      AddReplaceTexture(txd, txn, 'apocalypse_signs', txn)
      count = count + 1
    end
  end
  if not silent then
    print(('^2[apocalypse-road-signs]^7 applied %d highway texture replacements'):format(count))
  end
  return true
end

CreateThread(function()
  for _, delay in ipairs({0, 5000, 15000, 30000}) do
    Wait(delay)
    applyReplacements()
  end
end)

-- Highway and gantry dictionaries stream by region. Re-register quietly so
-- late-loaded sign assets cannot fall back to their clean embedded textures.
CreateThread(function()
  while true do
    Wait(10000)
    applyReplacements(true)
  end
end)

AddEventHandler('playerSpawned', function()
  CreateThread(function()
    Wait(2500)
    applyReplacements()
  end)
end)

AddEventHandler('onResourceStop', function(resource)
  if resource ~= GetCurrentResourceName() then return end
  for txd, textures in pairs(replacements) do
    for _, txn in ipairs(textures) do RemoveReplaceTexture(txd, txn) end
  end
end)
